import {normalizeView,timelineLayout,visibleWindow,scrollForBeat} from './timeline.js';
const $=s=>document.querySelector(s);
export function createTimelineUI({getProject,getView,setView,getClip,navigatePiano,followPiano,isInteracting,toast}){
 const scroller=$('.arrangement-scroll'),inner=$('#arrangement');let layout=null,refreshing=false;
 function labels(){if(!layout)return;const bars=getProject().bars,r=visibleWindow(layout,scroller.scrollLeft,bars),max=Math.max(1,bars-layout.visible+1);$('#timeline-visible').textContent=`第 ${r.first}–${r.last} / ${bars} 小节`;$('#timeline-scroll').max=max;$('#timeline-scroll').value=Math.min(max,r.first);$('#timeline-start').max=max;if(document.activeElement!==$('#timeline-start'))$('#timeline-start').value=r.first;$('#timeline-scroll').disabled=!layout.maxScroll;$('#timeline-start').disabled=!layout.maxScroll;$('#timeline-clip').disabled=!getClip();}
 function refresh(){if(refreshing)return;refreshing=true;try{const p=getProject(),view=normalizeView(getView()),trackWidth=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--track-width'))||150,width=Math.max(trackWidth+32,scroller.clientWidth),beat=layout?scroller.scrollLeft/layout.beatWidth:0;layout={...timelineLayout(p.bars,width,trackWidth,view.zoom),bars:p.bars};inner.style.minWidth='0';inner.style.width=layout.width+'px';scroller.scrollLeft=scrollForBeat(layout,beat);$('#timeline-zoom').value=view.zoom;$('#timeline-follow').checked=view.follow;labels()}finally{refreshing=false}}
 function jump(bar){if(!layout)return;const max=+$('#timeline-start').max;if(!Number.isInteger(bar)||bar<1||bar>max){toast(`视窗起始小节须为 1–${max}，不改变播放位置。`);labels();return}scroller.scrollLeft=scrollForBeat(layout,(bar-1)*4);navigatePiano((bar-1)*4);labels()}
 function reveal(start,length=4){const view=normalizeView(getView()),zoom=length<=32?'8':length<=64?'16':length<=128?'32':'fit';setView({...view,zoom});refresh();scroller.scrollLeft=scrollForBeat(layout,start);navigatePiano(start);labels()}
 $('#timeline-zoom').onchange=()=>{setView({...normalizeView(getView()),zoom:$('#timeline-zoom').value});refresh()};$('#timeline-follow').onchange=()=>setView({...normalizeView(getView()),follow:$('#timeline-follow').checked});$('#timeline-scroll').oninput=()=>jump(+$('#timeline-scroll').value);$('#timeline-start').onchange=()=>jump(+$('#timeline-start').value);$('#timeline-start').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();jump(+e.currentTarget.value);e.currentTarget.blur();labels()}};$('#timeline-start').onblur=labels;$('#timeline-clip').onclick=()=>{const c=getClip();if(c)reveal(c.start,c.length)};scroller.addEventListener('scroll',labels);const observer=new ResizeObserver(refresh);observer.observe(scroller);
 function follow(beat){if(!layout||!getView().follow||isInteracting())return;const range=visibleWindow(layout,scroller.scrollLeft,getProject().bars);if(beat<range.start||beat>range.end-1){scroller.scrollLeft=scrollForBeat(layout,beat,{anchor:.2});labels()}followPiano(beat)}
 return{refresh,reveal,follow,read:()=>layout?{...visibleWindow(layout,scroller.scrollLeft,getProject().bars),zoom:getView().zoom,follow:getView().follow,laneWidth:layout.laneWidth,scroll:scroller.scrollLeft}:null};
}
